const server = http.createServer((req, res) => {
  const url = new URL(req.url || '', 'http://localhost');
  const pathname = url.pathname;

  // @endpoint GET /health
  if (req.method === 'GET' && pathname === '/health') {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify({"status":"ok","service":"product-service"}));
  }

  // @endpoint GET /api/products
  if (req.method === 'GET' && pathname === '/api/products') {
    const category = url.searchParams.get('category');
    let results = PRODUCTS;
    if (category) {
      results = PRODUCTS.filter(
        (p) => p.category.toLowerCase() === category.toLowerCase()
      );
    }
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify(results));
  }

  // @endpoint GET /api/products/:id
  if (req.method === 'GET' && /^\/api\/products\/([^/]+)$/.test(pathname)) {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "No product exists with the given id." — explicit override via x-mock-response-code: 404
    if (requestedStatusCode === '404') {
      res.writeHead(404, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"error":"Product not found"}));
    }

    const id = pathname.match(/^\/api\/products\/([^/]+)$/)[1];
    const product = PRODUCTS.find((p) => p.id === id);

    // Real 404 for any id that isn't in the catalog — not just via the header override.
    if (!product) {
      res.writeHead(404, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"error":"Product not found"}));
    }

    // "The requested product." — default
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify(product));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Endpoint not defined' }));
});

server.listen(PORT);
